import { apiFetch,getAtlasClient } from "/modules/atlas-client.js";
const $=selector=>document.querySelector(selector);const client=await getAtlasClient();const {data}=await client.auth.getSession();if(!data.session)location.replace("/#passes");
function render(ticket){if(!ticket){$("#queuePosition").textContent="—";$("#queueTitle").textContent="Você ainda não está na fila.";$("#queueMessage").textContent="Escolha um passe e confirme o PIX para receber sua posição.";$("#buyPass").classList.remove("hidden");return}const position=Math.max(1,Number(ticket.position||1)),total=Number(ticket.total||967),ready=position<=1||ticket.status==="ready";$("#queuePosition").textContent=position;$("#sessionDuration").textContent=`${ticket.durationMinutes} min`;$("#estimatedWait").textContent=ready?"Agora":`~${ticket.estimatedMinutes} min`;$("#ticketStatus").textContent=ready?"Pronto":ticket.priority?"Prioridade ativa":"Na fila";$("#queueProgress").style.width=`${Math.max(2,Math.min(100,(1-position/total)*100))}%`;$("#statusKicker").textContent=ready?"SUA SESSÃO ESTÁ PRONTA":ticket.priority?"FILA PRIORITÁRIA · SUA POSIÇÃO":"SUA POSIÇÃO NA FILA";$("#queueTitle").textContent=ready?"É a sua vez de jogar.":`Você está na posição #${position}.`;$("#queueMessage").textContent=ready?"O servidor está reservando sua sessão nesta tela.":ticket.priority?"Sua sessão completa avança com prioridade. A página atualiza automaticamente.":"Sua posição avança automaticamente até a sessão ser liberada."}
async function refresh(){try{const queue=await apiFetch("/api/cloud-queue");render(queue.myTicket)}catch(error){$("#queueMessage").textContent=error.message}}refresh();setInterval(refresh,12000);$("#homeButton").addEventListener("click",()=>location.replace("/"));
